// routes/passwordReset.js
const express = require('express');
const router = express.Router();
const { MongoClient } = require('mongodb');
const crypto = require('crypto');
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many password reset attempts'
});

// 模拟用户存储
const users = [
  { id: 1, email: 'alice@example.com', resetToken: null, resetTokenExpiry: null },
  { id: 2, email: 'bob@example.com', resetToken: null, resetTokenExpiry: null }
];

router.post('/reset', limiter, async (req, res) => {
  const { email } = req.body;
  const client = new MongoClient(process.env.MONGO_URI);

  try {
    await client.connect();
    const db = client.db('app');

    // 防御1: 使用参数化查询（MongoDB 原生 $eq 操作符）
    const user = await db.collection('users').findOne({
      email: { $eq: email }  // line 24: 参数化查询，阻断 NoSQL 注入
    });

    if (!user) {
      // 统一错误响应，防止用户枚举
      return res.status(200).json({ message: 'If the email exists, a reset link has been sent.' });
    }

    // 防御2: 生成高熵随机令牌
    const resetToken = crypto.randomBytes(32).toString('hex');
    const tokenHash = crypto.createHash('sha256').update(resetToken).digest('hex');
    const expiry = Date.now() + 3600000; // 1小时

    await db.collection('users').updateOne(
      { _id: user._id },
      { $set: { resetToken: tokenHash, resetTokenExpiry: expiry } }
    );

    // 防御3: 使用参数化查询验证令牌
    const verifyToken = (token) => {
      const hash = crypto.createHash('sha256').update(token).digest('hex');
      return db.collection('tokens').findOne({
        tokenHash: { $eq: hash },  // line 45: 参数化查询，且存储的是哈希而非明文
        expiry: { $gt: Date.now() }
      });
    };

    // 模拟发送邮件（实际会调用邮件服务）
    console.log(`Reset link: /reset/confirm?token=${resetToken}`);

    res.json({ message: 'Reset link sent' });
  } catch (err) {
    console.error('Password reset error:', err);
    res.status(500).json({ message: 'Internal server error' });
  } finally {
    await client.close();
  }
});

module.exports = router;

