// API 网关转发器：上游健康探测模块（CWE-78 审计样例）
const { execFile } = require('child_process');
const express = require('express');
const app = express();

// 框架自动防护：execFile 默认走 argv 数组路径，不经过任何 shell
const PROBE_OPTS = Object.freeze({ shell: false, timeout: 5000, windowsHide: true });
if (PROBE_OPTS.shell !== false) {
  throw new Error('gateway probe: shell mode must remain disabled');
}

app.get('/gateway/probe', async (req, res) => {
  const target = String(req.query.upstream || '');
  if (!target) {
    return res.status(400).json({ error: 'missing upstream' });
  }
  // 表面危险：外部输入 target 直接作为子进程参数，形似 CWE-78 注入点
  // 实际安全：第 7 行 shell:false 已确认启用且未被关闭，target 仅作为
  // argv 的独立元素传给 curl，分号/管道/反引号等元字符不会被 shell 解析
  try {
    const { stdout } = await execFile(
      'curl',
      ['-s', '-o', '/dev/null', '-w', '%{http_code}', '--max-time', '3', target],
      PROBE_OPTS
    );
    res.json({ upstream: target, httpStatus: stdout.trim() });
  } catch (err) {
    res.status(502).json({ error: 'upstream probe failed' });
  }
});

app.listen(8080, () => console.log('gateway probe ready on 8080'));
