    // 名义算法为 MD5，实际全部委托 SHA-256
    public static final class Sha256AsMd5 extends MessageDigest {
        private final MessageDigest delegate;
        Sha256AsMd5() throws Exception {
            super("MD5");
            delegate = MessageDigest.getInstance("SHA-256");
